import{_ as n,c as i,o as e,ae as s}from"./chunks/framework.BlRNOFgT.js";const p=JSON.parse('{"title":"Latihan Soal: Usability & Monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/usability-monitoring.md","filePath":"WBD/usability-monitoring.md"}'),t={name:"WBD/usability-monitoring.md"};function l(r,a,u,g,m,k){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="latihan-soal-usability-monitoring" tabindex="-1">Latihan Soal: Usability &amp; Monitoring <a class="header-anchor" href="#latihan-soal-usability-monitoring" aria-label="Permalink to &quot;Latihan Soal: Usability &amp; Monitoring&quot;">​</a></h1><h2 id="bagian-1-definisi-standar-usability" tabindex="-1">Bagian 1: Definisi &amp; Standar Usability <a class="header-anchor" href="#bagian-1-definisi-standar-usability" aria-label="Permalink to &quot;Bagian 1: Definisi &amp; Standar Usability&quot;">​</a></h2><p><strong>1. Manakah dari elemen berikut yang secara eksplisit dinyatakan sebagai parameter utama dalam definisi standar industri (ISO 9241-11:2018) untuk mengukur sejauh mana sebuah sistem dapat digunakan untuk mencapai tujuan tertentu?</strong></p><ul><li>A. Effectiveness (Efektivitas)</li><li>B. Learnability (Kemudahan dipelajari)</li><li>C. Efficiency (Efisiensi)</li><li>D. Memorability (Daya ingat)</li><li>E. Satisfaction (Kepuasan)</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Definisi ISO 9241-11 berfokus pada tiga pilar utama: Efektivitas, Efisiensi, dan Kepuasan. Learnability dan Memorability adalah komponen kualitas usabilitas menurut Jakob Nielsen, bukan bagian dari definisi inti ISO tersebut, meskipun saling berkaitan.</p></details><hr><p><strong>2. Dalam kerangka kerja Jakob Nielsen, atribut kualitas apa saja yang harus dipenuhi untuk memastikan sebuah desain antarmuka memiliki usabilitas yang baik?</strong></p><ul><li>A. Errors (Tingkat dan pemulihan kesalahan)</li><li>B. Engagement (Keterlibatan pengguna)</li><li>C. Memorability (Kemudahan mengingat kembali cara penggunaan)</li><li>D. Utility (Kegunaan fitur)</li><li>E. Learnability (Kemudahan penyelesaian tugas pertama kali)</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> 5 Atribut Nielsen adalah: Learnability, Efficiency, Memorability, Errors, dan Satisfaction. Engagement adalah bagian dari 5Es Whitney Quesenbery. Utility sering dibedakan dari Usabilitas dalam konteks apakah sistem melakukan apa yang dibutuhkan (fungsionalitas) vs bagaimana cara melakukannya.</p></details><hr><p><strong>3. Sebuah tim pengembang sedang melakukan pengujian usabilitas saat produk masih dalam tahap pengembangan aktif (in-development). Manakah pernyataan yang BENAR mengenai jenis pengujian ini (Formative Testing)?</strong></p><ul><li>A. Tujuannya adalah mendiagnosis dan memperbaiki masalah spesifik.</li><li>B. Memerlukan jumlah partisipan yang besar untuk validitas statistik.</li><li>C. Dilakukan untuk menetapkan baseline metrik kepatuhan terhadap persyaratan (requirements).</li><li>D. Biasanya dilakukan dalam iterasi berulang dengan studi skala kecil.</li><li>E. Menghasilkan data kualitatif tentang mengapa pengguna mengalami kesulitan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, D, E</strong></p><p><strong>Penjelasan:</strong> Formative testing bersifat diagnostik dan iteratif (skala kecil). Opsi B dan C adalah karakteristik dari Summative testing yang dilakukan di akhir pengembangan untuk validasi metrik dan perbandingan statistik.</p></details><hr><p><strong>4. Mengapa metodologi pengujian dengan hanya menggunakan 5 pengguna (test users) dianggap valid dan efisien dalam banyak skenario pengembangan?</strong></p><ul><li>A. Karena 5 pengguna sudah cukup untuk menemukan 100% dari semua masalah usabilitas.</li><li>B. Karena setelah pengguna ke-5, kurva penemuan masalah menjadi jenuh (diminishing returns).</li><li>C. Karena 5 pengguna dapat mengungkap sekitar 85% dari masalah usabilitas utama.</li><li>D. Karena pengujian statistik yang valid selalu membutuhkan minimal 30 pengguna.</li><li>E. Karena lebih baik melakukan iterasi desain dan tes ulang daripada menghabiskan waktu mengamati hal yang sama berulang kali.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Kurva Nielsen menunjukkan bahwa 5 pengguna menemukan ~85% masalah. Menambah pengguna di atas 5 hanya memberikan sedikit wawasan baru (buang waktu). Opsi A salah karena tidak mungkin 100%. Opsi D kontradiktif dengan prinsip &quot;Discount Usability&quot;.</p></details><hr><p><strong>5. Manakah yang termasuk dalam dimensi usabilitas menurut klasifikasi 5Es dari Whitney Quesenbery?</strong></p><ul><li>A. Error tolerant (Toleransi kesalahan)</li><li>B. Effective (Efektif)</li><li>C. Emotional (Emosional)</li><li>D. Engaging (Menarik/Mengikat)</li><li>E. Easy to learn (Mudah dipelajari)</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> 5Es terdiri dari: Effective, Efficient, Engaging, Error tolerant, dan Easy to learn. Emotional bukan istilah teknis yang digunakan dalam klasifikasi 5Es ini, meskipun Engaging mencakup aspek kepuasan interaksi.</p></details><hr><h2 id="bagian-2-design-user-experience" tabindex="-1">Bagian 2: Design &amp; User Experience <a class="header-anchor" href="#bagian-2-design-user-experience" aria-label="Permalink to &quot;Bagian 2: Design &amp; User Experience&quot;">​</a></h2><p><strong>6. Dalam upaya membersihkan pengalaman pengguna (Clean Up User Experience), strategi manakah yang disarankan untuk mengurangi beban kognitif pengguna?</strong></p><ul><li>A. Menciptakan antarmuka yang benar-benar unik dan belum pernah ada sebelumnya agar stand-out.</li><li>B. Menggunakan pola desain yang mirip dengan layanan internet populer (seperti Amazon atau Google).</li><li>C. Memastikan konsistensi penyelesaian tugas di seluruh halaman aplikasi.</li><li>D. Menambah jumlah klik navigasi (deep hierarchy) untuk mengategorikan informasi secara lebih spesifik.</li><li>E. Mengeliminasi atau memindahkan elemen &quot;birokrasi&quot; situs (logo berlebih, kebijakan) ke bagian bawah.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A adalah jebakan; disarankan untuk tidak menciptakan antarmuka unik hanya demi keunikan (&quot;Copy successful services&quot;), karena pengguna menghabiskan waktu di situs lain dan terbiasa dengan pola umum. Opsi D salah karena setiap klik tambahan meningkatkan risiko pengguna meninggalkan situs sebesar 50%.</p></details><hr><p><strong>7. Saat merancang persona pengguna untuk pengujian, faktor lingkungan dan fisik apa yang membedakan pengguna nyata dari pengembang (developer)?</strong></p><ul><li>A. Pengembang biasanya menggunakan layar 20 inci, sedangkan pengguna mobile mungkin hanya beberapa inci.</li><li>B. Pengguna nyata selalu memiliki koneksi internet yang lebih cepat daripada lingkungan development kantor.</li><li>C. Pengembang mengetik ~60 kata per menit, sedangkan pengguna mobile mungkin hanya 5-10 kata per menit.</li><li>D. Pengguna mobile mungkin menggunakan aplikasi sambil berjalan di jalan yang ramai.</li><li>E. Pengguna nyata memiliki toleransi kesalahan sistem yang lebih tinggi daripada pengembang.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Slide menekankan perbedaan fisik dan konteks: ukuran layar, kecepatan mengetik, dan gangguan lingkungan (berjalan, keramaian). Opsi B salah (user seringkali punya koneksi lebih buruk). Opsi E salah (pengguna justru memiliki toleransi rendah terhadap kesulitan/error).</p></details><hr><h2 id="bagian-3-metodologi-testing" tabindex="-1">Bagian 3: Metodologi Testing <a class="header-anchor" href="#bagian-3-metodologi-testing" aria-label="Permalink to &quot;Bagian 3: Metodologi Testing&quot;">​</a></h2><p><strong>8. Apa saja syarat kondisi ideal untuk melakukan sesi pengujian usabilitas yang objektif?</strong></p><ul><li>A. Pengembang produk harus duduk di samping pengguna untuk membimbing jika mereka bingung.</li><li>B. Tidak ada bantuan (assistance) dari pengembang produk selama tes berlangsung.</li><li>C. Pengamatan dilakukan melalui cermin satu arah (one-way mirror) atau rekaman video.</li><li>D. Lingkungan tes harus tenang dan nyaman bagi subjek tes.</li><li>E. Subjek tes haruslah seorang ahli komputer agar bisa mengkritik kode program.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A sangat dilarang karena membiaskan hasil tes (pengembang tidak akan ada di samping user di dunia nyata). Opsi E salah; subjek tes harus merepresentasikan target pengguna rata-rata, bukan ahli teknis (kecuali target pasarnya memang ahli teknis).</p></details><hr><p><strong>9. Selama mengobservasi subjek tes, metrik atau perilaku apa yang menjadi indikator utama adanya masalah usabilitas?</strong></p><ul><li>A. Seberapa cepat pengguna menyelesaikan tugas (waktu).</li><li>B. Apakah pengguna berhenti (stuck) pada langkah tertentu.</li><li>C. Apakah pengguna menyatakan kebingungan tentang langkah selanjutnya.</li><li>D. Apakah pengguna menyukai palet warna yang digunakan.</li><li>E. Berapa banyak klik acak yang dilakukan pengguna saat bingung.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, E</strong></p><p><strong>Penjelasan:</strong> Fokus utama pengujian adalah performa dan hambatan: waktu, getting stuck, kebingungan (confusion), dan perilaku mengklik acak (clicking randomly). Opsi D (preferensi warna) bersifat subjektif dan bukan indikator utama hambatan fungsional/alur tugas dalam konteks ini.</p></details><hr><p><strong>10. Sebagai seorang administrator sistem, informasi apa yang dapat Anda simpulkan dan tindak lanjuti dari data log server?</strong></p><ul><li>A. Banyak permintaan ke URL yang tidak ada (404) → Indikasi adanya broken links.</li><li>B. Tingginya Server Errors → Indikasi adanya kode yang rusak (broken code).</li><li>C. Pengguna meninggalkan sesi di halaman tertentu (last page viewed) → Halaman tersebut mungkin memerlukan klarifikasi antarmuka.</li><li>D. Data demografis detail (Nama, Alamat Rumah) → Tersedia secara default di log standar HTTP.</li><li>E. Browser dan OS yang digunakan → Membantu memutuskan platform mana yang perlu investasi lebih.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi D salah besar; log server standar (seperti Apache/Nginx) hanya mencatat IP, User Agent, dan Request, tidak mencatat data pribadi pengguna secara detail tanpa mekanisme tambahan. Opsi A, B, C, dan E adalah inferensi logis yang diajarkan untuk monitoring.</p></details><hr><h2 id="bagian-4-strategi-business-impact" tabindex="-1">Bagian 4: Strategi &amp; Business Impact <a class="header-anchor" href="#bagian-4-strategi-business-impact" aria-label="Permalink to &quot;Bagian 4: Strategi &amp; Business Impact&quot;">​</a></h2><p><strong>11. Dalam kasus aplikasi berbasis forum atau komunitas, bagaimana strategi yang valid untuk mengatasi masalah ketiadaan konten awal (kosong)?</strong></p><ul><li>A. Membayar setiap pengguna secara tunai untuk setiap postingan yang mereka buat.</li><li>B. Menciptakan sistem insentif non-moneter, seperti &quot;Reviewer Rank&quot; atau lencana reputasi.</li><li>C. Menunggu pengguna datang dengan sendirinya tanpa intervensi (organik).</li><li>D. Menggunakan gamifikasi untuk memberi penghargaan atas perilaku yang diinginkan.</li><li>E. Mengandalkan administrator untuk memposting konten awal (seeding) dan menghapus thread buatan sendiri setelah tes selesai.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> Solusi yang ditekankan (studi kasus Amazon) adalah pengakuan reputasi (recognition/rank), bukan pembayaran tunai (Opsi A tidak sustainable). Opsi C adalah penyebab masalah &quot;Chicken and Egg&quot; itu sendiri. Opsi E adalah langkah pengujian, bukan solusi jangka panjang untuk akuisisi pengguna.</p></details><hr><p><strong>12. Grafik hubungan antara kompleksitas aplikasi dan pengalaman pengguna (user experience/sophistication) menunjukkan tren yang mana?</strong></p><ul><li>A. Pengguna menjadi semakin canggih seiring waktu, mengejar kompleksitas aplikasi.</li><li>B. Aplikasi tumbuh semakin kompleks (JavaScript, Flash, dll.).</li><li>C. Persentase pengguna dengan pengalaman tinggi (sophisticated) cenderung menurun atau stagnan relatif terhadap kompleksitas sistem.</li><li>D. Adanya kesenjangan (gap) yang semakin membesar antara kemampuan user rata-rata dengan kompleksitas fitur web.</li><li>E. Aplikasi berbasis teks murni kembali menjadi tren untuk meningkatkan usabilitas.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Grafik menunjukkan garis kompleksitas naik, sementara garis persentase user with experience menurun/stagnan, menciptakan &quot;User Experience Gap&quot;. Opsi A salah karena realitanya pengguna tertinggal. Opsi E tidak relevan dengan tren kompleksitas teknis yang dibahas.</p></details><hr><p><strong>13. Kasus kebangkrutan Webvan ($1.2 Milyar) dijadikan contoh untuk menyoroti implikasi apa?</strong></p><ul><li>A. Harga produk yang terlalu mahal adalah penyebab utama kegagalan e-commerce.</li><li>B. Usabilitas yang inferior dapat menyebabkan kegagalan bisnis total.</li><li>C. Pengguna tidak akan memberikan &quot;kesempatan kedua&quot; jika mereka kesulitan menggunakan situs.</li><li>D. Pentingnya berinvestasi pada armada pengiriman daripada antarmuka web.</li><li>E. Setiap klik tambahan yang tidak perlu meningkatkan peluang pengguna meninggalkan situs (abandonment) sebesar 50%.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Webvan gagal karena usabilitas yang buruk (inferior usability). Poin tentang &quot;50% chance of abandonment on extra click&quot; adalah statistik pendukung yang menjelaskan mengapa usabilitas buruk berdampak fatal secara bisnis.</p></details><hr><p><strong>14. Jika log akses standar (Access Log) tidak memberikan informasi yang cukup, langkah teknis apa yang dapat diambil untuk memperkaya data monitoring?</strong></p><ul><li>A. Mengkonfigurasi server HTTP untuk menambahkan cookie header contents ke dalam log.</li><li>B. Memodifikasi aplikasi untuk mencatat aktivitas pengguna tambahan ke dalam RDBMS.</li><li>C. Membangun data warehouse multidimensi untuk aktivitas pengguna.</li><li>D. Menghapus semua log lama agar server lebih cepat mencatat log baru.</li><li>E. Menggunakan alat analisis flow atau dashboard (seperti Google Analytics).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi D adalah tindakan pemeliharaan server, bukan teknik memperkaya informasi (Information You Need to Record). Opsi A, B, C, dan E adalah langkah-langkah eskalasi dari monitoring dasar ke monitoring analitik tingkat lanjut.</p></details><hr><p><strong>15. Dalam skenario pengujian aplikasi forum, tugas mana yang valid diberikan kepada pengguna untuk menguji fungsionalitas inti?</strong></p><ul><li>A. &quot;Jelajahi situs sesuka Anda selama 10 menit.&quot;</li><li>B. &quot;Cari apakah pertanyaan X sudah pernah ditanyakan; jika belum, posting pertanyaan tersebut.&quot;</li><li>C. &quot;Login sebagai admin dan hapus semua user dari database.&quot;</li><li>D. &quot;Jawab pertanyaan yang baru saja Anda posting sendiri dengan menggunakan akun dummy lain.&quot;</li><li>E. &quot;Coba temukan halaman &#39;Tentang Kami&#39; dan bacalah sejarah perusahaan.&quot;</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> Tugas pengujian harus spesifik dan berorientasi pada goal (Task-based), bukan eksplorasi bebas (Opsi A) atau tugas trivia yang tidak menguji fungsi utama (Opsi E). Opsi C berbahaya dan destruktif untuk tes pengguna umum (biasanya tugas admin dipisah). Opsi B dan D adalah langkah logis dalam Example usability Flow.</p></details><hr><h2 id="bagian-5-best-practices-analytics" tabindex="-1">Bagian 5: Best Practices &amp; Analytics <a class="header-anchor" href="#bagian-5-best-practices-analytics" aria-label="Permalink to &quot;Bagian 5: Best Practices &amp; Analytics&quot;">​</a></h2><p><strong>16. Saat subjek tes tampak sangat bingung dan mulai mengklik secara acak, apa yang harus dilakukan pengamat menurut praktik terbaik?</strong></p><ul><li>A. Segera menghentikan tes dan memberi tahu jawaban yang benar.</li><li>B. Membiarkan subjek melanjutkan sampai mereka menemukan jalan keluar atau menyerah sendiri.</li><li>C. Mencatat langkah-langkah acak tersebut sebagai data kesalahan.</li><li>D. Menanyakan &quot;Mengapa Anda mengklik itu?&quot; setiap kali mereka melakukan klik.</li><li>E. Memberikan penalti waktu pada skor akhir.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> Intervensi (Opsi A) merusak data. Pertanyaan konstan (Opsi D) mengganggu proses kognitif. Praktik yang benar adalah observasi pasif: biarkan user berjuang (let the subject continue) untuk melihat pola kesalahan alami mereka.</p></details><hr><p><strong>17. Mengapa penting untuk memonitor dari mana pengunjung berasal (misal: Google vs NYTimes.com) dan berapa nilai transaksi mereka?</strong></p><ul><li>A. Untuk memblokir pengunjung dari situs pesaing.</li><li>B. Untuk menentukan alokasi anggaran iklan (Ad spend) ke sumber yang menghasilkan high-profit users.</li><li>C. Untuk mengetahui efektivitas kampanye pemasaran.</li><li>D. Untuk mengubah tampilan web secara otomatis berdasarkan asal pengunjung.</li><li>E. Untuk menghitung Return on Investment (ROI) dari berbagai kanal trafik.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Analisis sumber trafik (referral) dikaitkan dengan perilaku pembelian (dollar amounts) bertujuan untuk keputusan bisnis: &quot;buy more ads from the place that sends high-profit users&quot;.</p></details><hr><p><strong>18. Pernyataan &quot;Those with limited knowledge in a domain suffer a dual burden&quot; menyiratkan masalah apa dalam konteks usabilitas?</strong></p><ul><li>A. Pengguna sering kali membuat kesalahan (regrettable errors).</li><li>B. Pengguna tidak menyadari bahwa mereka telah membuat kesalahan (incompetence robs ability to realize).</li><li>C. Pengguna cenderung menyalahkan sistem padahal mereka yang salah.</li><li>D. Pengguna ahli lebih sulit dipuaskan daripada pengguna pemula.</li><li>E. Kesalahan pengguna tidak dapat diperbaiki melalui desain antarmuka.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B</strong></p><p><strong>Penjelasan:</strong> Kutipan tersebut menyoroti dua beban: 1) Membuat kesimpulan/kesalahan yang salah, dan 2) Ketidakmampuan untuk menyadari kesalahan tersebut (robs them of the ability to realize it). Ini menekankan pentingnya sistem yang memandu atau error-tolerant.</p></details><hr><p><strong>19. Apa wawasan yang bisa didapatkan jika Anda hanya melakukan tes dengan 1 orang pengguna saja?</strong></p><ul><li>A. Tidak ada wawasan sama sekali (0 insight) karena sampel terlalu kecil.</li><li>B. Sekitar sepertiga (1/3) dari semua masalah usabilitas dapat ditemukan.</li><li>C. Wawasan yang cukup untuk memulai perbaikan awal sebelum tes lebih lanjut.</li><li>D. Data statistik yang cukup untuk mempublikasikan jurnal ilmiah.</li><li>E. Validasi bahwa produk sudah siap rilis.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> Sesuai grafik &quot;Usability Problems Found&quot;: 0 user = 0 insight, 1 user = ~1/3 masalah ditemukan. Ini jauh lebih baik daripada 0 dan memberikan data awal yang berharga (formative), meskipun belum cukup untuk statistik (Opsi D) atau rilis final (Opsi E).</p></details><hr><p><strong>20. Menurut materi, elemen apa yang seharusnya menjadi pembeda utama antara satu situs web dengan situs web lainnya agar sukses?</strong></p><ul><li>A. Antarmuka (Interface) yang unik dan inovatif.</li><li>B. Konten (Content) yang unik.</li><li>C. Cara navigasi yang berbeda dari standar industri.</li><li>D. Kreativitas tombol dan ikon yang artistik.</li><li>E. Nilai informasi atau layanan yang ditawarkan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, E</strong></p><p><strong>Penjelasan:</strong> &quot;It is unique content that should distinguish one Web site from another, not unique interface.&quot; Pengguna menginginkan antarmuka yang familiar (birokrasi minimal) agar mereka bisa fokus pada konten/layanan unik yang ditawarkan situs tersebut.</p></details>',85)])])}const d=n(t,[["render",l]]);export{p as __pageData,d as default};
